+static int
+cifs_debug_instance_refresh(void)
+{
+    int sts;
+    char buffer[PATH_MAX], inst_name[PATH_MAX];
+    FILE *fp;
+
+    pmInDom debug_svr_indom = INDOM(CIFS_DEBUG_SVR_INDOM);
