+	if (strncmp(strtrim(buffer), "Minimum 5 Volts (mV):", 16) == 0)
+		sscanf(buffer, "%*s%*s%*s%*s %"SCNu64"", &farm_scsi_log_stats->minimum_5_volts);
+
