     if (registry->labels)
 	free(registry->labels);
+    registry->labels = NULL;
+    registry->nlabels = 0;

     mmv_stats_stop(registry->file, registry->addr);
+    registry->addr = NULL;
+}
+
+void
+mmv_stats_free(mmv_registry_t *registry)
+{
+    mmv_stats_reset(registry);
     memset(registry, 0, sizeof(mmv_registry_t));
     free(registry);
 }
